/// The subset of [`LookParams`] a tonescale preset overrides.
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
pub struct ToneParams {
    pub tn_con: f32,
    pub tn_sh: f32,
    pub tn_toe: f32,
    pub tn_off: f32,
    pub tn_hcon_enable: f32,
    pub tn_hcon: f32,
    pub tn_hcon_pv: f32,
    pub tn_hcon_st: f32,
    pub tn_lcon_enable: f32,
    pub tn_lcon: f32,
    pub tn_lcon_w: f32,
}

impl ToneParams {
    /// The fields in declaration (DCTL) order.
    pub fn to_array(&self) -> [f32; 11] {
        [self.tn_con, self.tn_sh, self.tn_toe, self.tn_off, self.tn_hcon_enable, self.tn_hcon, self.tn_hcon_pv, self.tn_hcon_st, self.tn_lcon_enable, self.tn_lcon, self.tn_lcon_w]
    }

    /// Inverse of [`ToneParams::to_array`].
    pub fn from_array(a: &[f32; 11]) -> Self {
        Self { tn_con: a[0], tn_sh: a[1], tn_toe: a[2], tn_off: a[3], tn_hcon_enable: a[4], tn_hcon: a[5], tn_hcon_pv: a[6], tn_hcon_st: a[7], tn_lcon_enable: a[8], tn_lcon: a[9], tn_lcon_w: a[10] }
    }
}

impl ToneParams {
    /// Overwrite the tonescale fields of `look`.
    pub fn apply_to(&self, look: &mut LookParams) {
        look.tn_con = self.tn_con;
        look.tn_sh = self.tn_sh;
        look.tn_toe = self.tn_toe;
        look.tn_off = self.tn_off;
        look.tn_hcon_enable = self.tn_hcon_enable;
        look.tn_hcon = self.tn_hcon;
        look.tn_hcon_pv = self.tn_hcon_pv;
        look.tn_hcon_st = self.tn_hcon_st;
        look.tn_lcon_enable = self.tn_lcon_enable;
        look.tn_lcon = self.tn_lcon;
        look.tn_lcon_w = self.tn_lcon_w;
    }
}

